// Content Idea Generator using Claude
const contentTopics = [
  'productivity tips',
  'tech innovations',
  'startup insights',
  'AI developments',
  'coding best practices',
  'entrepreneurship',
  'remote work',
  'digital marketing',
  'social media trends',
  'business automation'
];

const contentFormats = [
  'carousel post',
  'single image post',
  'quote post',
  'behind-the-scenes',
  'tutorial post',
  'infographic',
  'story series',
  'user-generated content',
  'poll post',
  'video post'
];

const randomTopic = contentTopics[Math.floor(Math.random() * contentTopics.length)];
const randomFormat = contentFormats[Math.floor(Math.random() * contentFormats.length)];

const prompt = `Create an engaging Instagram ${randomFormat} about ${randomTopic}. 

Please provide:
1. Main caption (engaging, with emojis, under 2200 characters)
2. Hashtags (mix of popular and niche, 20-25 hashtags)
3. Content description for visuals
4. Best posting time suggestion
5. Engagement strategy

Make it authentic, valuable, and aligned with a tech/business audience.`;

return [{
  json: {
    topic: randomTopic,
    format: randomFormat,
    claude_prompt: prompt,
    timestamp: new Date().toISOString()
  }
}];

// Parse Claude's response and structure for Instagram
const response = $input.first().json.content;
const originalData = $('Content Idea Generator').first().json;

// Extract sections from Claude's response
const sections = response.split('\n\n');

let caption = '';
let hashtags = '';
let visualDescription = '';
let postingTime = '';
let engagementStrategy = '';

// Parse each section
sections.forEach(section => {
  if (section.includes('caption') || section.includes('Caption')) {
    caption = section.replace(/.*caption:?/i, '').trim();
  } else if (section.includes('hashtag') || section.includes('Hashtag')) {
    hashtags = section.replace(/.*hashtag:?/i, '').trim();
  } else if (section.includes('visual') || section.includes('Visual')) {
    visualDescription = section.replace(/.*visual:?/i, '').trim();
  } else if (section.includes('time') || section.includes('Time')) {
    postingTime = section.replace(/.*time:?/i, '').trim();
  } else if (section.includes('engagement') || section.includes('Engagement')) {
    engagementStrategy = section.replace(/.*engagement:?/i, '').trim();
  }
});

// Clean up hashtags
if (hashtags && !hashtags.startsWith('#')) {
  hashtags = hashtags.split(' ').map(tag => 
    tag.startsWith('#') ? tag : `#${tag}`
  ).join(' ');
}

// Create structured content
const instagramPost = {
  id: `post_${Date.now()}`,
  topic: originalData.topic,
  format: originalData.format,
  caption: caption,
  hashtags: hashtags,
  visualDescription: visualDescription,
  suggestedPostingTime: postingTime,
  engagementStrategy: engagementStrategy,
  createdAt: new Date().toISOString(),
  status: 'draft',
  platform: 'instagram'
};

return [{
  json: instagramPost
}];

// Select best image and enhance content
const postData = $('Content Parser').first().json;
const imageResults = $input.first().json.results;

let selectedImage = null;
if (imageResults && imageResults.length > 0) {
  // Select highest quality image
  selectedImage = imageResults.reduce((best, current) => 
    (current.likes > best.likes) ? current : best
  );
}

// Enhanced post data with image
const enhancedPost = {
  ...postData,
  image: selectedImage ? {
    url: selectedImage.urls.regular,
    downloadUrl: selectedImage.urls.full,
    altText: selectedImage.alt_description || postData.visualDescription,
    photographer: selectedImage.user.name,
    photographerUrl: selectedImage.user.links.html,
    unsplashUrl: selectedImage.links.html
  } : null,
  readyToPost: true
};

// Add attribution if using Unsplash image
if (selectedImage) {
  enhancedPost.caption += `\n\n📸 Photo by ${selectedImage.user.name} on Unsplash`;
}

return [{
  json: enhancedPost
}];

